export function dashboardLegend(){return h('p',{class:'small dashboard-legend','data-testid':'dashboard-legend'},
 h('span',{class:'value-input'},'INPUT · editable boxes'), ' · ',h('span',{class:'value-measured'},'MEASURED · read-only file evidence'), ' · ',h('span',{class:'value-calculated'},'CALCULATED · labelled read-only results'), ' · ',h('span',{class:'value-planned'},'PLANNED · conditional, not performed'),'. Amber = caution / unknown; HOLD is a stop, not permission to inject.');}

function controlBody(p){return h('div',h('p',h('strong',`${p.moduleLabel}: `),p.moduleFunction),
 h('p',{class:'small'},`${p.categoryMark?.mark||''} ${p.categoryMark?.label||p.category} · ${p.controlledAt||'verify control location'}`),
 h('p',{class:p.range.known?'small':'small warn'},h('strong','Admissible range / units: '),p.range.text,p.range.requiredField?` Required: ${p.range.requiredField}.`:''),
 table(['Retention','Selectivity','Efficiency'],[h('tr',...['retention','selectivity','efficiency'].map(k=>h('td',p.effects[k])))]),
 h('p',{class:'tiny'},p.equipment),h('p',{class:'tiny'},p.sources.join(' · ')));}
export function decisionEquipment(s,e,{print=false}={}){
 const controls=decisionControls(s,e);if(!controls.length)return null;
 return h('section',{'data-testid':print?'print-decision-controls':'decision-controls'},h('h3','Where to make this change'),
 h('p',{class:'small'},`Based on ${e.current.label}. ${controls.map(p=>`${p.label} → ${p.moduleLabel}`).join('; ')}. Select a control for its effects and run-specific limits. ▪ Mechanical · ● Chemical · ◐ Both.`),
 controls.map(p=>{const content=controlBody(p);if(print)return h('section',h('h4',p.label),content);const d=details(`${p.label} · ${p.moduleLabel}`,false,content);d.dataset.testid='decision-control-'+p.key;return d;}));
}
