export function nextMethodSummary(s,e){
 const d=e.current,p=e.nextPlanned;if(!d)return null;
 if(!p)return h('section',{'data-testid':'next-method-summary'},h('h3',d.status==='EFFICIENCY_NEXT'?'FC1 hand-off · no next injection':'Next experiment conditions'),h('p',{class:'small'},d.status==='EFFICIENCY_NEXT'?FC1_HANDOFF_NOTE:d.status==='N'?'No passing numerical recipe yet. Do not turn the failed predictions into an injection method; review model inputs and actual available stock.':d.status==='BLANK'?'Acquire the first sample using your approved starting method. A blank does not establish an optimised sample recipe.':'No complete recipe issued for the current observation / investigation. Resolve the stated check first; do not guess the next %B or invent a performed experiment.'));
 const r=s.runs.find(x=>x.id===d.runId),m=runColumn(s,r).model,c=p.conditions,records=p.methodRecords||[],rec=k=>records.find(x=>x.key===k),read=k=>rec(k)?.value??'Unknown',text=(v,u='')=>v===null||v===undefined?'Unknown — verify before injection':`${v}${u?' '+u:''}`;
 const apparatus=runInstrument(s,r),instrument=apparatus.confirmed?apparatus.instrument.label:r.profileExtras?.hplcNo?`Recorded HPLC ${r.profileExtras.hplcNo} — descriptor, not verified current apparatus`:'Actual instrument not linked — verify your next injection setup';
 const rows=[['Instrument',instrument],['Mode',read('mode')],['Column / chemistry',`${m?.product||m?.ligand||'Unknown chemistry'} · ${text(c.L,'mm')} × ${text(c.ID,'mm')} · ${text(c.PS,'µm')} · ${c.bead||'bead type unconfirmed'}`],['Mobile phase / composition',`${c.organic||'Unknown solvent'} · ${text(c.percentB,'%B')}`],['Flow',text(c.F,'mL/min')],['Temperature',c.temperature==='ambient'?'Ambient — not a numeric oven setpoint':text(c.temperature,'°C')],['Injection / detector',`${text(rec('injVolume')?.value,'µL')} · ${text(rec('wavelength')?.value,'nm')}`],['Sample / concentration',`${read('sampleType')} · ${text(rec('sampleConc')?.value,rec('sampleConc')?.unit)}`],['pH / acquisition window',`pH ${read('pH')} · ${text(rec('acquisitionTime')?.value,'min')}; verify the window covers later peaks`]];
 const unknown=[...new Set([...records.filter(x=>x.value===null&&!['sampleId','additiveConc','additiveUnit'].includes(x.key)&&!(x.key==='mixAcnPct'&&c.organic!=='Mix')).map(x=>x.label),...recipeEvidence(r).missing])];
 return h('section',{'data-testid':'next-method-summary'},h('h3','Next experiment · conditional recipe'),h('p',{class:'small'},`Source: measured ${d.label}. Change only the stated strategy; carry the other recorded conditions below. A planned recipe is not a completed run or clearance to inject.`),table(['Condition','Next setting / check'],rows.map(([k,v])=>h('tr',h('td',k),h('td',v)))),
 d.stage==='selectivity'?h('p',{class:'small'},e.model.qualified?`The qualified Retention fit is a separate reference (minimum ${e.model.calculation.B}%B). This plan uses the composition stated in NEXT ACTION and its measured run history; the fit does not prove separation at a changed temperature or solvent.`:`The Retention fit is not qualified: no minimum %B is issued. Selectivity is supported by ${d.label}'s measured peak count, time and Rs / floor. ${c.percentB}%B is the measured/reference composition in the stated strategy, not a fitted minimum.`):null,
 h('p',{class:unknown.length?'small warn':'small'},unknown.length?`Not recorded in this CSV: ${unknown.join('; ')}. Verify the actual next-experiment method / bottle labels. These are not requests for historical group documents; unknowns are not auto-filled from a course example.`:'Carried method records are available; still verify actual apparatus and operating limits.'),
 h('button',{type:'button','data-testid':'next-method-full',onclick:()=>{const el=document.querySelector('[data-testid="planned-next"]');el?.scrollIntoView({behavior:'smooth',block:'start'});}},'Review full recipe, bottle source and carried-record provenance'));
}

export function plannedMethodTable(plan,{print=false}={}){return h('section',{'data-testid':print?'print-planned-method':'planned-method'},h('h4','Other next-run conditions · carried reference records'),
 h('p',{class:'small'},'Keep these recorded conditions unless the stated strategy changes them. Unknowns are not filled by defaults; source declarations and hardware limits still require verification. A solvent switch requires newly verified B-bottle contents.'),
 table(['Condition','Planned carry value','Unit','Source run / origin','State / check'],(plan.methodRecords||[]).map(x=>h('tr',h('td',x.label),h('td',x.value??'Unknown'),h('td',x.unit||'—'),h('td',`${x.sourceRunLabel} · ${x.source||'not recorded'}`),h('td',x.state,x.referenceValue!==null&&x.value===null?` · previous record: ${x.referenceValue}`:'',x.note?' · '+x.note:'')))),bottlePreparation(plan.documentedPreparation,{print}));}

export function submissionPanel(s,e){return details('Submission evidence · build record and rubric limits',false,
 h('section',{'data-testid':'submission-evidence'},h('h3','Build record: prepare it, then submit it yourself'),
 h('p',{class:'small'},'For the tool author’s assessment only. A laboratory user does not need an AI conversation, code repository or build record to import a CSV or use this workflow.'),
 h('p','Chenchen Lin · 34154760. AI-assisted web application, based on STU_084. The export below contains the packaged application source and the current recomputed decision evidence. It is not your complete AI conversation or an authorship declaration.'),
 h('ol',h('li','Export your session to preserve original CSVs and settings. Download the matching source/evidence record below.'),h('li','Export the complete AI conversation as a PDF with your name and student ID. Review the code and provide your own accurate declaration of authorship and AI assistance.'),h('li','Include your shareable site link and the required code repository link. Upload the build record through the course submission channel; this site does not upload or verify Moodle submissions.')),
 h('p',{class:'warn','data-testid':'rubric-boundaries'},'Assessment limits: compound identities are not inferred automatically, so candidate intermediates are not all-compound optima. Model-feasible stock plans require documented hardware and experimental validation. Automated tests do not prove that an unfamiliar person can complete the tool unaided. No grade or submission status is claimed.'),
 h('button',{type:'button','data-testid':'export-build-evidence',onclick:async ev=>{ev.target.disabled=true;try{const response=await fetch(new URL('../../audit/build-source.json',import.meta.url),{cache:'no-store'});if(!response.ok)throw Error('Matching packaged source is unavailable');const source=await response.json();if(source.appVersion!==APP_VERSION)throw Error('Packaged source differs from the running application');downloadText('HPLC_build_evidence_Chenchen_Lin_34154760.json',JSON.stringify({appVersion:APP_VERSION,exportedAt:new Date().toISOString(),student:{name:'Chenchen Lin',id:'34154760'},authorshipDeclaration:'Not supplied or verified by this tool. Student must provide an accurate declaration.',completeAIConversationIncluded:false,submissionVerified:false,packagedSource:source,currentEvidence:templateRecord(s,e)},null,2),'application/json');}catch(err){setUi(u=>{u.message=`Build evidence was not exported: ${err.message}. Export session separately; no incomplete source record was issued.`;});}finally{ev.target.disabled=false;}}},'Download matching source & decision evidence (.json)')));
}
